import {noseStageText,noseVitals,noseUnstable} from './nose-case.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,value='',disabled=false)=>`<button class="fish-button" data-nose-action="${action}" data-nose-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
export function nosePhoneHTML(t){return`<span class="modal-tag">☎ 急診會診</span><h2 id="modalTitle">ENT醫師，有一位鼻出血。</h2><div class="dialogue">NP：「急診有一位鼻出血的病人，想請你評估。」</div>${[{id:'bleeding',text:'還有再流嗎？',reply:'還有持續出血，急診正在協助初步止血。'},{id:'vitals',text:'Vital signs如何？',reply:noseVitals(t)},{id:'transfer',text:'目前適不適合上樓？',reply:t.variant==='unstable'?'現在不適合移動，請到急診一起處理。':'目前看起來穩定，可以安排上樓；你下急診看也可以。'}].map(q=>`<section>${btn((t.asked.includes(q.id)?'✓ ':'')+q.text,'ask',q.id,t.asked.includes(q.id))}${t.asked.includes(q.id)?`<p class="modal-copy">NP：「${esc(q.reply)}」</p>`:''}</section>`).join('')}${btn('到1F急診看病人','destination','f1',t.asked.length<3)}${btn('請病人到2G初診間','destination','g2',t.asked.length<3)}<p id="noseFeedback" class="fish-feedback" role="status"></p><button id="noseLater" class="text-button">保留來電，稍後回覆</button>`;}
export function noseHTML(t,message=''){
 const s=t.stage,location=t.dest==='g2'?'2G 初診間':'1F 急診';let body='';
 if(s==='arrival')body='<p class="modal-copy">病人到了，先重新確認生命徵象與出血狀況。</p>'+btn('重新評估病人','assess');
 if(s==='rescue')body=`<div class="dialogue">${t.dest==='g2'?'病人才剛到診療椅旁，突然冒冷汗、快要昏倒！':'病人持續出血、頭暈冒冷汗。'}<br><b>BP 78/46 · HR 128</b></div>${btn('呼叫支援，評估呼吸循環、處理休克並同步止血','rescue','support')}${btn('先繼續做fiber，等看完再說','rescue','scope')}`;
 if(s==='transfer')body='<p class="modal-copy">已呼叫支援並處理急變；與急診團隊協調後，由團隊陪同安全轉送。</p>'+btn('安排陪同轉回1F急診，接續處理','transfer');
 if(s==='history')body=`<div class="dialogue">${noseUnstable(t)?'團隊已處理急變，重新評估後接續鼻出血處置。':'目前意識清楚，仍有鼻出血。'}</div>${[{id:'course',text:'出血多久、哪一側、先前怎麼處理？',answer:'今天開始反覆流，先捏鼻子但還是流。'},{id:'medication',text:'相關病史與用藥，包括抗凝血藥？',answer:'已核對病史及用藥，與團隊一併納入處理評估。'}].map(q=>btn((t.history.includes(q.id)?'✓ ':'')+q.text,'history',q.id,t.history.includes(q.id))+(t.history.includes(q.id)?'<p class="modal-copy">'+q.answer+'</p>':'')).join('')}${btn('用fiber檢查出血點 →','fiber','',t.history.length<2)}`;
 if(s==='scope')body=`<div class="fish-view"><svg viewBox="0 0 480 260" role="img" aria-label="鼻腔fiber簡化示意"><defs><radialGradient id="noseMucosa"><stop stop-color="#c79388"/><stop offset="1" stop-color="#34242c"/></radialGradient></defs><rect width="480" height="260" fill="#182b34"/><ellipse cx="240" cy="130" rx="205" ry="112" fill="url(#noseMucosa)"/><path d="M175 40Q220 130 175 220M300 50Q235 130 300 210" fill="none" stroke="#d4a494" stroke-width="29"/><ellipse cx="290" cy="148" rx="23" ry="14" fill="#a53e44"/><text x="20" y="24" fill="#d3dbcd" font-size="12">FIBER / NASAL VIEW</text></svg><button class="fish-bone" style="left:60%;top:57%" data-nose-action="locate" aria-label="標記出血點" ${t.located?'disabled':''}>${t.located?'✓':'＋'}</button></div><p class="modal-copy">${t.located?'出血點已確認。':'點選視野中的出血點。'}</p>${btn('接續止血 →','scope-done','',!t.located)}`;
 if(s==='bosmin')body='<p class="modal-copy">依檢查所見先處理出血，觀察止血反應。</p>'+btn('使用Bosmin止血綿packing','bosmin');
 if(s==='packing')body=`<div class="dialogue">${t.variant==='mild'?'止血後只剩小量滲血。':'止血後仍有大量出血，需要進一步packing。'}</div>${btn('Surgicel packing','packing','surgicel')}${btn('Merocel packing','packing','merocel')}`;
 if(s==='recheck')body='<p class="modal-copy">已完成'+(t.packing==='surgicel'?'Surgicel':'Merocel')+' packing，還要確認止血效果。</p>'+btn('重新評估出血與生命徵象','recheck');
 if(s==='foley')body='<div class="dialogue">Merocel後仍有大量出血，尚未控制。</div>'+btn('與團隊評估加上Foley，再確認止血效果','foley','add')+btn('已經塞過了，直接讓病人回家','foley','home');
 if(s==='tae')body='<div class="dialogue">加上Foley後仍持續出血。</div>'+btn('聯繫介入團隊評估TAE，安排住院','tae','refer')+btn('繼續等，不聯繫其他團隊','tae','wait');
 if(s==='disposition')body=`<section class="fish-case-note"><b>本次處置</b><p>${({surgicel:'Surgicel packing後，出血已控制、狀況穩定。',merocel:'Merocel packing後，出血已控制、狀況穩定。',foley:'Merocel加上Foley後已控制出血。',tae:'Packing仍無法控制，已聯繫TAE評估。'})[t.packing]}</p></section>${btn('交代追蹤、再出血時回院評估','finish','followup')}${btn('交代三天後回診移除Merocel，說明再出血注意事項','finish','three-days')}${btn('安排住院，交接處置與後續照護','finish','admit')}`;
 return`<span class="modal-tag">急診鼻出血 · ${location}</span><h2 id="modalTitle">${noseStageText(t)}</h2><p class="fish-patient">${esc(t.patient.name)}</p>${body}<p id="noseFeedback" class="fish-feedback" role="status">${esc(message)}</p><footer class="fish-footer"><small>科內娛樂的簡化情境</small><button id="noseLater" class="text-button">先離開，進度保留 →</button></footer>`;
}
export function bindNose({act,later}){document.querySelectorAll('[data-nose-action]').forEach(b=>b.onclick=()=>act(b.dataset.noseAction,b.dataset.noseValue));document.getElementById('noseLater').onclick=later;}
